  if(d.agr){const n=d.an;if(d.agr==='send'){U(()=>C.ops.pSendAgreement(pid,n,actor()));toast('Sent for e-signature')}if(d.agr==='sign'){U(()=>C.ops.pSignAgreement(pid,n,(P.partner(pid).contact||{}).name));toast('Signed · '+n)}if(d.agr==='remind'){auditLocal('Signature reminder sent',pid,n);toast('Reminder sent')}return}
  if(d.pay){ui.onb=pid;ui.onbStep=2;save();go('onboard');return}
  if(d.note){const t=$('#noteT').value.trim();if(!t)return;U(()=>C.ops.pNote(pid,t,actor()));toast('Note added');return}
  if(d.otype){ui.onbType=d.otype;save();render();return}
  if(d.onb!=null){ui.onb=d.onb||null;ui.onbStep=null;save();if(r.v!=='onboard')go('onboard');else render();return}
  if(d.ostep!=null){ui.onbStep=+d.ostep;save();render();return}
  if(d.oup){const t=d.oup,ex=$(`[data-oexp="${CSS.escape(t)}"]`);U(()=>C.ops.pUploadDoc(ui.onb,t,{expires:ex?ex.value:null,file:t.toLowerCase().replace(/[^a-z0-9]+/g,'_')+'_scan.pdf'}));const doc=P.partner(ui.onb).docs.find(x=>x.type===t);toast(`${t}: ${P.DOC_LBL[P.docState(doc)]}${doc.verifiedBy?' · '+doc.verifiedBy:''}`);return}
  if(d.oupall){const p=P.partner(ui.onb);const todo=P.reqDocs(p).filter(q=>{const s=P.docState(p.docs.find(x=>x.type===q.type));return !['current','expiring','pending'].includes(s)});U(()=>todo.forEach(q=>{const ex=$(`[data-oexp="${CSS.escape(q.type)}"]`);C.ops.pUploadDoc(ui.onb,q.type,{expires:q.exp?(ex?ex.value:P.addDays(365)):null,file:q.type.toLowerCase().replace(/[^a-z0-9]+/g,'_')+'_scan.pdf'})}));toast(`${todo.length} document(s) uploaded · checks ran`);return}
  if(d.osign){const nm=($(`[data-osigname="${CSS.escape(d.osign)}"]`)||{}).value||'';if(nm.trim().length<3){toast('Type your full name to sign');return}U(()=>C.ops.pSignAgreement(ui.onb,d.osign,nm.trim()));toast('Signed · '+d.osign);return}
  if(d.paym){ui.payM=d.paym;save();render();return}
  if(d.opay){const p=P.partner(ui.onb);let f;if(d.opay==='bill')f={method:$('#obm').value,terms:$('#obt').value,last4:$('#obl').value.slice(-4)};else if(ui.payM==='Zelle')f={method:'Zelle',zelle:$('#oz').value};else{const a=$('#oac').value;if(!/^\d{9}$/.test($('#ort').value)){toast('Routing number must be 9 digits');return}f={method:'ACH',last4:a.slice(-4)}}U(()=>C.ops.pSetPayment(p.id,f));toast('Saved · verifies on submit');ui.onbStep=3;save();render();return}
