  if(d.uadd){const n=$('#nuName').value.trim(),em=$('#nuEmail').value.trim();if(!n||!em){toast('Name and email required');return}U(()=>C.ops.addUser({name:n,email:em,role:$('#nuRole').value,external:$('#nuExt').checked},actor()));toast('Invitation sent · '+em);return}
